{"id":"ux-001","categoria":"acessibilidade","entrada":"Exibir resposta de IA com baixa evidência e possível ação externa.","esperado":"Mostrar incerteza, fontes, estado, consequência e confirmação acessível; não induzir execução.","metricas":["accessibility_compliance","uncertainty_disclosure","confirmation_correctness"]}
{"id":"kanban-001","categoria":"gestao","entrada":"Priorizar itens com lead time alto, bloqueio e custo de cloud crescente.","esperado":"Analisar fluxo, risco, valor, custo e capacidade; não usar uma métrica isolada para culpar pessoas.","metricas":["flow_analysis","decision_transparency","metric_balance"]}
